      mast.position.set(p[0], 4.3, p[2]); mast.castShadow = true; scene.add(mast);
      const panel = new THREE.Mesh(new THREE.BoxGeometry(.8, .25, .35), new THREE.MeshBasicMaterial({ color: '#e8fff6' })); panel.position.set(p[0], 8.85, p[2]); scene.add(panel);
    });
    const stadium = new THREE.Group(); scene.add(stadium);
    const ground = new THREE.Mesh(new THREE.CircleGeometry(14, 96), new THREE.MeshStandardMaterial({ color: '#173e2c', roughness: .95 }));
    ground.rotation.x = -Math.PI / 2; ground.position.y = -.15; ground.receiveShadow = true; stadium.add(ground);
    const outfield = new THREE.Mesh(new THREE.CircleGeometry(9, 96), new THREE.MeshStandardMaterial({ color: '#287348', roughness: .94 }));
    outfield.rotation.x = -Math.PI / 2; outfield.position.y = -.11; outfield.receiveShadow = true; stadium.add(outfield);
    const inner = new THREE.Mesh(new THREE.CircleGeometry(5.2, 96), new THREE.MeshStandardMaterial({ color: '#328653', roughness: .95 }));
    inner.rotation.x = -Math.PI / 2; inner.position.y = -.09; stadium.add(inner);
    const pitch = new THREE.Mesh(new THREE.BoxGeometry(1.7, .12, 6.6), new THREE.MeshStandardMaterial({ color: '#c8a576', roughness: 1 }));
    pitch.position.set(0, .02, 0); pitch.receiveShadow = true; stadium.add(pitch);
    for (let z of [-2.4, 2.4]) {
      const crease = new THREE.Mesh(new THREE.BoxGeometry(2.6, .015, .07), new THREE.MeshBasicMaterial({ color: '#f7f0d7' })); crease.position.set(0, .09, z); stadium.add(crease);
      for (let x of [-.25, 0, .25]) { const stump = new THREE.Mesh(new THREE.CylinderGeometry(.035, .035, .68, 7), new THREE.MeshStandardMaterial({ color: '#eee1c5' })); stump.position.set(x, .41, z + (z > 0 ? .35 : -.35)); stadium.add(stump); }
    }
    const boundary = new THREE.Mesh(new THREE.TorusGeometry(8.5, .045, 6, 100), new THREE.MeshBasicMaterial({ color: '#92d99a', transparent: true, opacity: .8 }));
    boundary.rotation.x = Math.PI / 2; boundary.position.y = -.02; stadium.add(boundary);
    const stands = new THREE.Group(); stadium.add(stands);
    for (let row = 0; row < 5; row++) {
      const radius = 9.5 + row * .72;
      const arc = new THREE.Mesh(new THREE.TorusGeometry(radius, .34, 5, 100, Math.PI * 1.87), new THREE.MeshStandardMaterial({ color: row % 2 ? '#18382d' : '#234336', roughness: 1 }));
      arc.rotation.x = Math.PI / 2; arc.position.y = 1.2 + row * .46; stands.add(arc);
      const ribbon = new THREE.Mesh(new THREE.TorusGeometry(radius + .25, .045, 4, 100, Math.PI * 1.87), new THREE.MeshBasicMaterial({ color: row % 2 ? '#476e56' : '#345c49' }));
      ribbon.rotation.x = Math.PI / 2; ribbon.position.y = 1.15 + row * .46; stands.add(ribbon);
    }
    const crowd = new THREE.Group(); stadium.add(crowd);
    const crowdColors = ['#d6a64d', '#a8485d', '#6c9bc8', '#d2d3b1', '#43a180', '#b26cce'];
    for (let i = 0; i < 430; i++) {
      const angle = Math.random() * Math.PI * 2, radius = 9.9 + Math.random() * 3.1;
      const x = Math.cos(angle) * radius, z = Math.sin(angle) * radius;
      const dot = new THREE.Mesh(new THREE.BoxGeometry(.08, .08, .07), new THREE.MeshBasicMaterial({ color: crowdColors[Math.floor(Math.random() * crowdColors.length)] }));
      dot.position.set(x, .85 + Math.random() * 2.5, z); crowd.add(dot);
    }
    const playerGroup = new THREE.Group(); stadium.add(playerGroup);
    function makePlayer(x, z, jersey, pose = 0) {
      const g = new THREE.Group(); g.position.set(x, .04, z);
