      playerGroup.add(g); return g;
    }
    const batter = makePlayer(.48, 1.7, '#18b883', 1); batter.rotation.y = Math.PI;
    const bowler = makePlayer(-.22, -1.6, '#eeeeeb', 0);
    [[-4.8, -3.4], [4.8, -2.7], [-6.4, 1], [6.1, 2.2], [-3.6, 5], [3.8, 5.2], [-7.3, -1.2], [7, -3.8]].forEach((p, i) => { const f = makePlayer(p[0], p[1], i % 2 ? '#f0eee3' : '#e5eee0', i % 3 === 0); f.scale.setScalar(.78); f.rotation.y = Math.atan2(-p[0], -p[1]); });
