    let targetY = 1.1, orbit = 0, dragging = false, prevX = 0, prevY = 0, ballAnim = null, lightPulse = 0;
    canvas.addEventListener('pointerdown', e => { dragging = true; prevX = e.clientX; prevY = e.clientY; canvas.setPointerCapture(e.pointerId); });
    canvas.addEventListener('pointermove', e => { if (!dragging) return; orbit += (e.clientX - prevX) * .006; targetY = Math.max(.4, Math.min(3.1, targetY + (e.clientY - prevY) * .015)); prevX = e.clientX; prevY = e.clientY; });
    canvas.addEventListener('pointerup', () => dragging = false); canvas.addEventListener('pointercancel', () => dragging = false);
    function resize() { const w = canvas.clientWidth || 1, h = canvas.clientHeight || 1; renderer.setSize(w, h, false); camera.aspect = w / h; camera.updateProjectionMatrix(); }
    const clock = new THREE.Clock();
    function animate() {
      const t = clock.getElapsedTime(); orbit += .00065; camera.position.x = Math.sin(orbit) * 1.5; camera.position.y += (targetY + 7.2 - camera.position.y) * .025; camera.position.z = 17.5 * Math.cos(orbit * .45); camera.lookAt(0, .65 + Math.sin(t * .22) * .08, 0);
      crowd.rotation.y = Math.sin(t * .15) * .018; batter.rotation.y = Math.PI + Math.sin(t * 1.2) * .04; bowler.rotation.y = Math.sin(t * .9) * .025;
      if (ballAnim) { const p = Math.min(1, (performance.now() - ballAnim.start) / ballAnim.duration); const curve = ballAnim.curve; ball.position.set((1 - p) * curve[0][0] + p * curve[2][0], curve[1][1] + Math.sin(p * Math.PI) * .65, curve[1][2] + (p - .5) * 2.4); ball.visible = true; if (p >= 1) { ball.visible = false; ballAnim = null; } }
      lightPulse = .93 + Math.sin(t * 1.8) * .07; stadiumLights.forEach(l => l.intensity = 18 * lightPulse);
      renderer.render(scene, camera); requestAnimationFrame(animate);
    }
    requestAnimationFrame(animate);
    sceneAPI = { resize, setTeam(team) { if (team) { batter.children[0].material.color.set(team.color); } }, ball(delivery = false) { ballAnim = { start: performance.now(), duration: delivery ? 720 : 540, curve: [[0, .55, -2.2], [0, 1.05, 0], [0, .55, 2.7]] }; }, resetBall() { ball.visible = false; ballAnim = null; } };
