function renderTeams() {
  $('teamGrid').innerHTML = TEAMS.map(team => `<button class="team-card" data-team="${team.id}" style="${teamStyle(team)}"><div class="team-card-head"><span class="team-crest">${team.short}</span><span class="team-city">${team.city}</span></div><div><h3>${team.name}</h3><p>${team.tagline}</p></div><span class="pick-label">PICK CLUB ↗</span></button>`).join('');
  $('teamGrid').querySelectorAll('.team-card').forEach(card => card.addEventListener('click', () => {
    selectedTeam = getTeamById(card.dataset.team); $('teamGrid').querySelectorAll('.team-card').forEach(c => c.classList.toggle('selected', c === card));
    startAuction();
  }));
}
function startAuction() {
  userSquad = []; budget = 100; lotIndex = 0;
  clubs = TEAMS.filter(t => t.id !== selectedTeam.id).map(t => ({ team: t, purse: 100, squad: [] }));
  if (sceneAPI) sceneAPI.setTeam(selectedTeam);
  $('arenaTeamName').textContent = `${selectedTeam.city} ${selectedTeam.name} · YOUR FRANCHISE`;
  $('stadiumScore').hidden = true;
  renderMiniTeams(); renderAuctionLot(); updatePurse(); renderSquad(); showScreen('auctionScreen');
}
function renderMiniTeams() {
  $('opponentMiniList').innerHTML = clubs.map(c => `<div class="mini-team" style="--team-color:${c.team.color}"><span class="team-crest">${c.team.short}</span><b>${c.team.city}</b><small>₹${c.purse} CR</small></div>`).join('');
}
function renderSquad() {
  $('squadCount').textContent = `${userSquad.length} / 5`;
  $('squadList').innerHTML = userSquad.length ? userSquad.map(p => `<div class="squad-player"><b>${p.name.split(' ')[0]} ${p.name.split(' ')[1][0]}.</b><span>${p.role} · ₹${p.price}cr</span></div>`).join('') : '<div class="empty-squad">Your first signing<br>is waiting out there.</div>';
}
function updatePurse() {
  $('purseAmount').textContent = budget;
  $('purseBar').style.width = `${Math.max(0, budget)}%`;
}
function playerArt(team, player) {
  return `<div class="player-art" style="--player-color:${team.color}99;--jersey:${team.color}"><div class="player-silhouette"><i class="head"></i><i class="body"></i><i class="arm left"></i><i class="arm right"></i><i class="legs"></i></div><span class="player-no">${player.num}</span></div>`;
}
function renderAuctionLot() {
  if (lotIndex >= PLAYERS.length || userSquad.length >= 5) { finishAuction(); return; }
  currentLot = PLAYERS[lotIndex]; currentBid = currentLot.base; lotSold = false;
  $('lotLabel').innerHTML = `LOT ${String(lotIndex + 1).padStart(2, '0')} <b>/ 12</b>`;
  $('auctionProgress').style.width = `${(lotIndex / PLAYERS.length) * 100}%`;
  $('playerLot').innerHTML = `${playerArt(selectedTeam, currentLot)}<div class="player-info"><div class="player-role">${currentLot.role} <span>·</span> LOT ${String(lotIndex + 1).padStart(2, '0')}</div><h3>${currentLot.name}</h3><div class="player-country">${currentLot.country} <span>·</span> AGE ${25 + (lotIndex * 3 % 9)}</div><div class="player-stats"><div class="stat"><b>${currentLot.bat}</b><span>BATTING</span></div><div class="stat"><b>${currentLot.bowl}</b><span>BOWLING</span></div><div class="stat"><b>${currentLot.field}</b><span>FIELDING</span></div></div></div><div class="player-price"><small>BASE PRICE</small><b>₹${currentLot.base}</b><span>CR · NO RESERVE</span></div>`;
  renderAuctionActions();
  $('auctionFeed').textContent = `${currentLot.name} is on the block. Make your move.`;
}
function renderAuctionActions() {
  const maxPlayers = userSquad.length >= 5;
  const canBid = !maxPlayers && budget >= currentBid && currentBid <= 25;
  const actions = $('auctionActions');
  actions.innerHTML = `<button class="bid-button" id="bidButton" ${canBid ? '' : 'disabled'}>MAKE BID · ₹${currentBid} CR</button><button class="pass-button" id="passButton">${budget < currentBid ? 'CAN’T AFFORD · PASS' : 'PASS LOT →'}</button>`;
  $('bidButton').addEventListener('click', bidOnLot);
  $('passButton').addEventListener('click', () => resolveLot(false, 'You passed on the lot. The other franchises are bidding.'));
}
